#[allow(dead_code)]
pub fn generated_a64_subset_match(word: u32) -> Option<&'static GeneratedInsnSpec> {
    let mut index = 0;
    while index < GENERATED_A64_SUBSET.len() {
        let spec = &GENERATED_A64_SUBSET[index];
        if spec.matches(word) {
            return Some(spec);
        }
        index += 1;
    }
    None
}

